using System.Collections.ObjectModel;
using System.ComponentModel;
using System.Windows;
using System.Windows.Data;
using NutrieGestao.Helpers;
using NutrieGestao.Models;
using NutrieGestao.Services;

namespace NutrieGestao.ViewModels;

public sealed class AppViewModel : ObservableObject
{
    // Antes de uma versão de produção, altere para false ou remova este bloco.
    private const bool CriarDadosDeExemploNoPrimeiroAcesso = true;
    private readonly DataService _data = new();
    private Empresa _empresa = new(); private Pagina _paginaAtual = Pagina.Dashboard; private bool _emConfiguracaoInicial; private string _mensagem = string.Empty;
    private Cliente? _clienteSelecionado; private Marmita? _marmitaSelecionada; private Pedido? _pedidoSelecionado; private Marmita? _marmitaDoItem; private int _quantidadeItem = 1;
    private Cliente? _clienteDoPedido; private DateTime _entregaDoPedido = DateTime.Today.AddDays(1); private FormaPagamento _formaPagamento = FormaPagamento.Pix; private decimal _valorPago; private string _observacoesPedido = string.Empty;
    private string _buscaCliente = string.Empty; private string _buscaMarmita = string.Empty; private string _buscaPedido = string.Empty;
    public AppViewModel()
    {
        Clientes = new(_data.LoadClientes().OrderBy(x => x.Nome)); Marmitas = new(_data.LoadMarmitas().OrderBy(x => x.Nome)); Pedidos = new(_data.LoadPedidos().OrderByDescending(x => x.DataPedido)); ItensDoPedido = [];
        Empresa = _data.LoadEmpresa() ?? new Empresa(); EmConfiguracaoInicial = string.IsNullOrWhiteSpace(Empresa.Nome);
        ClientesView = CollectionViewSource.GetDefaultView(Clientes); ClientesView.Filter = FilterCliente; MarmitasView = CollectionViewSource.GetDefaultView(Marmitas); MarmitasView.Filter = FilterMarmita; PedidosView = CollectionViewSource.GetDefaultView(Pedidos); PedidosView.Filter = FilterPedido;
        NavegarCommand = new RelayCommand<Pagina>(p => PaginaAtual = p); SalvarEmpresaCommand = new RelayCommand(SalvarEmpresa);
        NovoClienteCommand = new RelayCommand(() => ClienteSelecionado = new Cliente()); SalvarClienteCommand = new RelayCommand(SalvarCliente); ExcluirClienteCommand = new RelayCommand(ExcluirCliente);
        NovaMarmitaCommand = new RelayCommand(() => MarmitaSelecionada = new Marmita()); SalvarMarmitaCommand = new RelayCommand(SalvarMarmita); ExcluirMarmitaCommand = new RelayCommand(ExcluirMarmita);
        NovoPedidoCommand = new RelayCommand(NovoPedido); AdicionarItemCommand = new RelayCommand(AdicionarItem); RemoverItemCommand = new RelayCommand<OrderItemDraft>(i => { if (i != null) { ItensDoPedido.Remove(i); AtualizarTotaisPedido(); } }); SalvarPedidoCommand = new RelayCommand(SalvarPedido); ExcluirPedidoCommand = new RelayCommand(ExcluirPedido); AlterarStatusCommand = new RelayCommand<StatusPedido>(AlterarStatus);
    }
    public Empresa Empresa { get => _empresa; set => SetProperty(ref _empresa, value); } public bool EmConfiguracaoInicial { get => _emConfiguracaoInicial; set => SetProperty(ref _emConfiguracaoInicial, value); } public Pagina PaginaAtual { get => _paginaAtual; set => SetProperty(ref _paginaAtual, value); } public string Mensagem { get => _mensagem; set => SetProperty(ref _mensagem, value); }
    public ObservableCollection<Cliente> Clientes { get; } public ObservableCollection<Marmita> Marmitas { get; } public ObservableCollection<Pedido> Pedidos { get; } public ObservableCollection<OrderItemDraft> ItensDoPedido { get; } public ICollectionView ClientesView { get; } public ICollectionView MarmitasView { get; } public ICollectionView PedidosView { get; }
    public Array Statuses => Enum.GetValues(typeof(StatusPedido)); public Array FormasPagamento => Enum.GetValues(typeof(FormaPagamento)); public IReadOnlyList<string> TamanhosDisponiveis => NutrieGestao.Models.TamanhosMarmita.Valores; public IEnumerable<Marmita> MarmitasAtivas => Marmitas.Where(x => x.Ativo);
    public DashboardSummary ResumoDashboard => DashboardCalculator.Calcular(Pedidos, Clientes); public int PedidosEmAndamento => ResumoDashboard.PedidosEmAndamento; public int PedidosConcluidos => ResumoDashboard.PedidosConcluidos; public decimal FaturamentoTotal => ResumoDashboard.FaturamentoRecebido; public decimal FaturamentoMes => ResumoDashboard.FaturamentoDoMes; public IEnumerable<Pedido> PedidosRecentes => ResumoDashboard.PedidosRecentes;
    public Cliente? ClienteSelecionado { get => _clienteSelecionado; set => SetProperty(ref _clienteSelecionado, value); } public Marmita? MarmitaSelecionada { get => _marmitaSelecionada; set => SetProperty(ref _marmitaSelecionada, value); } public Pedido? PedidoSelecionado { get => _pedidoSelecionado; set => SetProperty(ref _pedidoSelecionado, value); } public Marmita? MarmitaDoItem { get => _marmitaDoItem; set => SetProperty(ref _marmitaDoItem, value); } public int QuantidadeItem { get => _quantidadeItem; set => SetProperty(ref _quantidadeItem, Math.Max(1, value)); } public Cliente? ClienteDoPedido { get => _clienteDoPedido; set => SetProperty(ref _clienteDoPedido, value); } public DateTime EntregaDoPedido { get => _entregaDoPedido; set => SetProperty(ref _entregaDoPedido, value); } public FormaPagamento FormaPagamento { get => _formaPagamento; set => SetProperty(ref _formaPagamento, value); } public decimal ValorPago { get => _valorPago; set { if (SetProperty(ref _valorPago, Math.Max(0, value))) AtualizarTotaisPedido(); } } public string ObservacoesPedido { get => _observacoesPedido; set => SetProperty(ref _observacoesPedido, value); }
    public decimal TotalDoPedido => ItensDoPedido.Sum(x => x.Subtotal); public decimal PendenteDoPedido => Math.Max(0, TotalDoPedido - ValorPago); public string BuscaCliente { get => _buscaCliente; set { if (SetProperty(ref _buscaCliente, value)) ClientesView.Refresh(); } } public string BuscaMarmita { get => _buscaMarmita; set { if (SetProperty(ref _buscaMarmita, value)) MarmitasView.Refresh(); } } public string BuscaPedido { get => _buscaPedido; set { if (SetProperty(ref _buscaPedido, value)) PedidosView.Refresh(); } }
    public System.Windows.Input.ICommand NavegarCommand { get; } public System.Windows.Input.ICommand SalvarEmpresaCommand { get; } public System.Windows.Input.ICommand NovoClienteCommand { get; } public System.Windows.Input.ICommand SalvarClienteCommand { get; } public System.Windows.Input.ICommand ExcluirClienteCommand { get; } public System.Windows.Input.ICommand NovaMarmitaCommand { get; } public System.Windows.Input.ICommand SalvarMarmitaCommand { get; } public System.Windows.Input.ICommand ExcluirMarmitaCommand { get; } public System.Windows.Input.ICommand NovoPedidoCommand { get; } public System.Windows.Input.ICommand AdicionarItemCommand { get; } public System.Windows.Input.ICommand RemoverItemCommand { get; } public System.Windows.Input.ICommand SalvarPedidoCommand { get; } public System.Windows.Input.ICommand ExcluirPedidoCommand { get; } public System.Windows.Input.ICommand AlterarStatusCommand { get; }
    private bool FilterCliente(object x) => x is Cliente c && (string.IsNullOrWhiteSpace(BuscaCliente) || c.Nome.Contains(BuscaCliente, StringComparison.OrdinalIgnoreCase) || c.Telefone.Contains(BuscaCliente, StringComparison.OrdinalIgnoreCase) || c.WhatsApp.Contains(BuscaCliente, StringComparison.OrdinalIgnoreCase));
    private bool FilterMarmita(object x) => x is Marmita m && (string.IsNullOrWhiteSpace(BuscaMarmita) || m.Nome.Contains(BuscaMarmita, StringComparison.OrdinalIgnoreCase));
    private bool FilterPedido(object x) => x is Pedido p && (string.IsNullOrWhiteSpace(BuscaPedido) || p.Numero.Contains(BuscaPedido, StringComparison.OrdinalIgnoreCase) || p.NomeCliente.Contains(BuscaPedido, StringComparison.OrdinalIgnoreCase));
    private void SalvarEmpresa() { if (string.IsNullOrWhiteSpace(Empresa.Nome) || string.IsNullOrWhiteSpace(Empresa.Responsavel)) { Avisar("Informe o nome da empresa e do responsável."); return; } _data.SaveEmpresa(Empresa); if (CriarDadosDeExemploNoPrimeiroAcesso && Clientes.Count == 0 && Marmitas.Count == 0 && Pedidos.Count == 0) CriarDadosDeExemplo(); EmConfiguracaoInicial = false; Mensagem = "Dados da empresa salvos com sucesso."; }
    private void SalvarCliente() { if (ClienteSelecionado == null || string.IsNullOrWhiteSpace(ClienteSelecionado.Nome)) { Avisar("Informe o nome do cliente."); return; } if (!Clientes.Contains(ClienteSelecionado)) Clientes.Add(ClienteSelecionado); _data.SaveClientes(Clientes); ClientesView.Refresh(); Mensagem = "Cliente cadastrado com sucesso."; }
    private void ExcluirCliente() { if (ClienteSelecionado == null) return; if (Pedidos.Any(p => p.ClienteId == ClienteSelecionado.Id)) { Avisar("Este cliente possui pedidos no histórico e não pode ser excluído."); return; } if (Confirmar($"Tem certeza que deseja excluir o cliente {ClienteSelecionado.Nome}?")) { Clientes.Remove(ClienteSelecionado); ClienteSelecionado = null; _data.SaveClientes(Clientes); Mensagem = "Cliente excluído."; } }
    private void SalvarMarmita() { if (MarmitaSelecionada == null || string.IsNullOrWhiteSpace(MarmitaSelecionada.Nome) || MarmitaSelecionada.Preco < 0) { Avisar("Informe nome e um preço válido para a marmita."); return; } if (!NutrieGestao.Models.TamanhosMarmita.EhValido(MarmitaSelecionada.Tamanho)) { Avisar("Selecione o tamanho 350g ou 500g."); return; } if (!Marmitas.Contains(MarmitaSelecionada)) Marmitas.Add(MarmitaSelecionada); _data.SaveMarmitas(Marmitas); MarmitasView.Refresh(); OnPropertyChanged(nameof(MarmitasAtivas)); Mensagem = "Marmita salva com sucesso."; }
    private void ExcluirMarmita() { if (MarmitaSelecionada == null) return; if (Pedidos.SelectMany(x => x.Itens).Any(i => i.MarmitaId == MarmitaSelecionada.Id)) { Avisar("Esta marmita possui pedidos no histórico. Marque-a como inativa para preservar os dados."); return; } if (Confirmar($"Tem certeza que deseja excluir a marmita {MarmitaSelecionada.Nome}?")) { Marmitas.Remove(MarmitaSelecionada); MarmitaSelecionada = null; _data.SaveMarmitas(Marmitas); } }
    private void NovoPedido() { PedidoSelecionado = null; ClienteDoPedido = null; ItensDoPedido.Clear(); ValorPago = 0; ObservacoesPedido = ""; EntregaDoPedido = DateTime.Today.AddDays(1); PaginaAtual = Pagina.Pedidos; Mensagem = "Preencha os dados abaixo para criar um novo pedido."; }
    private void AdicionarItem() { if (MarmitaDoItem == null) { Avisar("Selecione uma marmita para adicionar."); return; } var existente = ItensDoPedido.FirstOrDefault(x => x.Marmita.Id == MarmitaDoItem.Id); if (existente != null) existente.Quantidade += QuantidadeItem; else ItensDoPedido.Add(new OrderItemDraft(MarmitaDoItem, QuantidadeItem)); AtualizarTotaisPedido(); }
    private void SalvarPedido() { if (ClienteDoPedido == null || ItensDoPedido.Count == 0) { Avisar("Selecione um cliente e adicione pelo menos um item."); return; } if (ValorPago > TotalDoPedido) { Avisar("O valor pago não pode ser maior que o total do pedido."); return; } var pedido = new Pedido { Numero = ProximoNumero(), ClienteId = ClienteDoPedido.Id, NomeCliente = ClienteDoPedido.Nome, DataEntrega = EntregaDoPedido, FormaPagamento = FormaPagamento, ValorPago = ValorPago, Observacoes = ObservacoesPedido, Itens = ItensDoPedido.Select(x => new ItemPedido { MarmitaId = x.Marmita.Id, NomeMarmita = x.Marmita.Nome, Quantidade = x.Quantidade, ValorUnitario = x.Marmita.Preco, Ingredientes = CopiarIngredientes(x.Marmita.Ingredientes) }).ToList() }; Pedidos.Insert(0, pedido); _data.SavePedidos(Pedidos); AtualizarIndicadores(); NovoPedido(); Mensagem = $"Pedido #{pedido.Numero} cadastrado com sucesso."; }
    private void ExcluirPedido() { if (PedidoSelecionado != null && Confirmar($"Tem certeza que deseja excluir o pedido #{PedidoSelecionado.Numero}?")) { Pedidos.Remove(PedidoSelecionado); PedidoSelecionado = null; _data.SavePedidos(Pedidos); AtualizarIndicadores(); Mensagem = "Pedido excluído."; } }
    private void AlterarStatus(StatusPedido status) { if (PedidoSelecionado == null) return; PedidoSelecionado.Status = status; _data.SavePedidos(Pedidos); PedidosView.Refresh(); AtualizarIndicadores(); Mensagem = "Status do pedido atualizado."; }
    private string ProximoNumero() => (Pedidos.Select(p => int.TryParse(p.Numero, out var n) ? n : 0).DefaultIfEmpty().Max() + 1).ToString("D6"); private void AtualizarTotaisPedido() { OnPropertyChanged(nameof(TotalDoPedido)); OnPropertyChanged(nameof(PendenteDoPedido)); } private void AtualizarIndicadores() { OnPropertyChanged(nameof(ResumoDashboard)); OnPropertyChanged(nameof(PedidosEmAndamento)); OnPropertyChanged(nameof(PedidosConcluidos)); OnPropertyChanged(nameof(FaturamentoTotal)); OnPropertyChanged(nameof(FaturamentoMes)); OnPropertyChanged(nameof(PedidosRecentes)); }
    private void CriarDadosDeExemplo()
    {
        var cliente = new Cliente { Nome = "Maria Oliveira", Telefone = "(11) 98888-1111", WhatsApp = "(11) 98888-1111", Cidade = "São Paulo", Bairro = "Centro" };
        var marmita = new Marmita { Nome = "Frango grelhado com arroz integral", Descricao = "Frango, arroz integral, feijão e brócolis", Categoria = "Linha Equilíbrio", Tamanho = "350g", Preco = 18m };
        Clientes.Add(cliente); Marmitas.Add(marmita);
        Pedidos.Add(new Pedido { Numero = "000001", ClienteId = cliente.Id, NomeCliente = cliente.Nome, DataEntrega = DateTime.Today.AddDays(1), Status = StatusPedido.Novo, FormaPagamento = FormaPagamento.Pix, ValorPago = 18m, Itens = [new ItemPedido { MarmitaId = marmita.Id, NomeMarmita = marmita.Nome, Quantidade = 2, ValorUnitario = marmita.Preco }] });
        _data.SaveClientes(Clientes); _data.SaveMarmitas(Marmitas); _data.SavePedidos(Pedidos); AtualizarIndicadores();
    }
    private static List<IngredienteMarmita> CopiarIngredientes(IEnumerable<IngredienteMarmita> ingredientes) => ingredientes.Select(ingrediente => new IngredienteMarmita { Nome = ingrediente.Nome, QuantidadePorMarmita = ingrediente.QuantidadePorMarmita, Unidade = ingrediente.Unidade, CustoPorcao = ingrediente.CustoPorcao }).ToList();
    private static void Avisar(string mensagem) => MessageBox.Show(mensagem, "Nutriê Gestão", MessageBoxButton.OK, MessageBoxImage.Information); private static bool Confirmar(string mensagem) => MessageBox.Show(mensagem, "Nutriê Gestão", MessageBoxButton.YesNo, MessageBoxImage.Question) == MessageBoxResult.Yes;
}
